-- Filename generated by official Supabase CLI 2.122.0 in CI40754399163.
begin;
set local lock_timeout='5s';
alter table public.cardforge_studio_documents add column catalog_dependencies jsonb;

create or replace function public.cardforge_source_contained_css_image(p_value text)
returns boolean language plpgsql immutable security invoker set search_path='' as $$
declare value text:=btrim(p_value); depth integer:=0; i integer; name text;
begin
 if value in ('','none') then return true; end if;
 if value !~* '^(repeating-)?(linear|radial)-gradient\(' or value ~ '[^a-zA-Z0-9#.,()%+[:space:]-]' then return false; end if;
 for i in 1..length(value) loop
   if substr(value,i,1)='(' then
     name:=lower((regexp_match(left(value,i-1),'([a-zA-Z-]+)[[:space:]]*$'))[1]);
     if name is null or name not in ('linear-gradient','radial-gradient','repeating-linear-gradient','repeating-radial-gradient','rgb','rgba','hsl','hsla') then return false; end if;
     depth:=depth+1;
   elsif substr(value,i,1)=')' then
     depth:=depth-1; if depth<0 then return false; end if;
   end if;
 end loop;
 return depth=0 and right(value,1)=')';
end $$;
revoke all on function public.cardforge_source_contained_css_image(text) from public,anon,authenticated;
grant execute on function public.cardforge_source_contained_css_image(text) to service_role;

create or replace function public.cardforge_studio_dependency_binding_valid(p_payload jsonb,p_revision integer,p_interpretation jsonb)
returns boolean language sql immutable security invoker set search_path='' as $$
 select coalesce(jsonb_typeof(p_interpretation)='object'
  and p_interpretation->>'contractVersion'='1'
  and p_interpretation->>'revision'=p_revision::text
  and p_interpretation->>'payloadDigest'=encode(extensions.digest(p_payload::text,'sha256'),'hex')
  and jsonb_typeof(p_interpretation->'complete')='boolean'
  and jsonb_typeof(p_interpretation->'references')='object'
  and jsonb_typeof(p_interpretation->'references'->'identities')='array'
  and jsonb_typeof(p_interpretation->'references'->'sources')='array'
  and not exists(select 1 from jsonb_array_elements((p_interpretation->'references'->'identities')||(p_interpretation->'references'->'sources')) v where jsonb_typeof(v)<>'string'),false);
$$;

-- Derived references separate canonical identity fields from source aliases;
-- display names and other prose never enter the identity comparison. The generic payload scanner alone cannot classify a bare identity.
create or replace function public.cardforge_studio_dependencies_mention(p_references jsonb,p_ids text[],p_sources text[])
returns boolean language sql immutable security invoker set search_path='' as $$
 select coalesce(((p_references->'identities') ?| p_ids)
   or public.cardforge_catalog_consumer_mentions(p_references->'sources','{}',p_sources),false);
$$;
revoke all on function public.cardforge_studio_dependencies_mention(jsonb,text[],text[]) from public,anon,authenticated;
grant execute on function public.cardforge_studio_dependencies_mention(jsonb,text[],text[]) to service_role;

create or replace function public.cardforge_guard_studio_catalog_dependencies()
returns trigger language plpgsql security invoker set search_path='' as $$
declare request jsonb; target record; aliases text[]; ids text[]; old_mentions boolean:=false;
begin
 if tg_op='UPDATE' and new.document_payload is not distinct from old.document_payload
   and new.revision=old.revision and new.catalog_dependencies is not distinct from old.catalog_dependencies then return new; end if;
 -- The native Studio/PostgREST writer uses READ COMMITTED. A pre-existing
 -- repeatable snapshot cannot establish absence of a newly committed Trash.
 -- Refuse that unsupported write boundary rather than claim NOWAIT refreshes it.
 if current_setting('transaction_isolation')<>'read committed' then
   raise exception 'studio_catalog_isolation_unsupported';
 end if;
 request:=new.catalog_dependencies;
 -- Only the trusted Studio writer sends the exact final payload alongside its
 -- interpretation. Ordinary/direct payload writers invalidate inherited proof.
 if request->'sourcePayload' is not distinct from new.document_payload
   and request->>'contractVersion'='1' and jsonb_typeof(request->'complete')='boolean'
   and jsonb_typeof(request->'references')='object'
   and jsonb_typeof(request->'references'->'identities')='array'
   and jsonb_typeof(request->'references'->'sources')='array'
   and jsonb_typeof(request->'opaqueReasons')='array'
   and not exists(select 1 from jsonb_array_elements((request->'references'->'identities')||(request->'references'->'sources')) v where jsonb_typeof(v)<>'string') then
   new.catalog_dependencies:=(request-'sourcePayload')||jsonb_build_object('revision',new.revision,
     'payloadDigest',encode(extensions.digest(new.document_payload::text,'sha256'),'hex'));
 else new.catalog_dependencies:=null;
 end if;
 -- ROW EXCLUSIVE has already been acquired on Studio. Catalog admission takes
 -- SHARE NOWAIT before lineage NOWAIT. Never wait on a lineage while retaining
 -- this writer lock; inspect retained state, not filtered discovery views.
 for target in select l.id,l.registry_asset_id from public.cardforge_pipeline_asset_lineages l
   where l.catalog_trashed_at is not null or l.catalog_claim_token is not null or l.catalog_claimed_at is not null
   for share nowait loop
   select coalesce(array_agg(distinct u) filter(where nullif(u,'') is not null),'{}') into aliases from (
     select r.url u from public.cardforge_asset_registry r where r.asset_id=target.registry_asset_id
     union all select r.preview_url from public.cardforge_asset_registry r where r.asset_id=target.registry_asset_id
     union all select s.source_url from public.cardforge_contributor_asset_submissions s where s.lineage_id=target.id
     union all select s.preview_url from public.cardforge_contributor_asset_submissions s where s.lineage_id=target.id
   ) sources;
   ids:=array_remove(array[target.id::text,target.registry_asset_id],null)||array(select id::text from public.cardforge_contributor_asset_submissions where lineage_id=target.id);
   if not public.cardforge_studio_dependency_binding_valid(new.document_payload,new.revision,new.catalog_dependencies)
      or new.catalog_dependencies->'complete' is distinct from 'true'::jsonb then
     raise exception 'studio_catalog_dependency_unverified';
   end if;
   old_mentions:=false;
   if tg_op='UPDATE' then old_mentions:=public.cardforge_catalog_consumer_mentions(old.document_payload,ids,aliases)
     or (public.cardforge_studio_dependency_binding_valid(old.document_payload,old.revision,old.catalog_dependencies)
       and public.cardforge_studio_dependencies_mention(old.catalog_dependencies->'references',ids,aliases)); end if;
   if (public.cardforge_catalog_consumer_mentions(new.document_payload,ids,aliases)
     or public.cardforge_studio_dependencies_mention(new.catalog_dependencies->'references',ids,aliases)) and not old_mentions then
     raise exception 'studio_catalog_reference_unavailable';
   end if;
 end loop;
 return new;
end $$;
create trigger cardforge_studio_catalog_dependencies before insert or update of document_payload,revision,catalog_dependencies
 on public.cardforge_studio_documents for each row execute function public.cardforge_guard_studio_catalog_dependencies();
revoke all on function public.cardforge_studio_dependency_binding_valid(jsonb,integer,jsonb) from public,anon,authenticated;
revoke all on function public.cardforge_guard_studio_catalog_dependencies() from public,anon,authenticated;
grant execute on function public.cardforge_studio_dependency_binding_valid(jsonb,integer,jsonb) to service_role;
grant execute on function public.cardforge_guard_studio_catalog_dependencies() to service_role;
-- Trusted source owner reconciliation: exact persisted payload and revision CAS,
-- without changing authored bytes or advancing document history. JSONB equality
-- and the digest both use PostgreSQL semantics; no JS serialization hash exists.
create or replace function public.cardforge_reconcile_studio_catalog_dependencies(
 p_owner_user_id text,p_document_id uuid,p_expected_revision integer,p_expected_payload jsonb,p_interpretation jsonb)
returns boolean language plpgsql security invoker set search_path='' as $$
declare affected integer;
begin
 if p_interpretation->'sourcePayload' is distinct from p_expected_payload then
   raise exception 'studio_catalog_interpretation_source_mismatch';
 end if;
 update public.cardforge_studio_documents set catalog_dependencies=p_interpretation
 where id=p_document_id and owner_user_id=p_owner_user_id and revision=p_expected_revision
   and document_payload=p_expected_payload;
 get diagnostics affected=row_count;
 return affected=1;
end $$;
revoke all on function public.cardforge_reconcile_studio_catalog_dependencies(text,uuid,integer,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.cardforge_reconcile_studio_catalog_dependencies(text,uuid,integer,jsonb,jsonb) to service_role;
create or replace function public.cardforge_catalog_consumer_inspectable(p jsonb, kind text, depth integer default 0)
returns boolean language plpgsql immutable security invoker set search_path='' as $$
declare strings text[]; numbers text[]; booleans text[]; nested text[]; k text; v jsonb; value text; child_kind text; child jsonb;
begin
 if depth>80 or jsonb_typeof(p) is distinct from 'object' then return false; end if;
 -- Studio's canonical parser accepts version-1 project documents, not an
 -- arbitrary wrapper. This subset includes all dependencies it can render;
 -- unproved card/data, package, custom-asset and production-plan paths stay opaque.
 if kind='studio' then
   if p->'version' is distinct from '1'::jsonb or jsonb_typeof(p->'userTemplates') is distinct from 'array' then return false; end if;
   for k,v in select * from jsonb_each(p) loop
     if k='version' then continue;
     elsif k in ('userTemplates','appearanceStyles') then
       if jsonb_typeof(v) is distinct from 'array' then return false; end if;
       for child in select * from jsonb_array_elements(v) loop
         if not public.cardforge_catalog_consumer_inspectable(child,case when k='userTemplates' then 'template' else 'style' end,depth+1) then return false; end if;
       end loop;
     elsif k in ('storedCards','cardSets','customFonts','mcpOperationReceipts') then
       if v is distinct from '[]'::jsonb then return false; end if;
     elsif k='customAssets' then
       if jsonb_typeof(v) is distinct from 'object' then return false; end if;
       if exists(select 1 from jsonb_each(v) a where a.key not in
         ('cardforge-maker-custom-textures','cardforge-maker-custom-dividers','cardforge-maker-custom-icons','cardforge-maker-custom-images')
         or a.value is distinct from '[]'::jsonb) then return false; end if;
     elsif k in ('exportSettings','productionPlan') then
       -- No dependency semantics are inferred from a nonempty auxiliary owner.
       if v is distinct from '{}'::jsonb then return false; end if;
     else return false;
     end if;
   end loop;
   return true;
 end if;
 numbers:='{}'; booleans:='{}'; nested:='{}';
 if kind='style' then
   if public.cardforge_valid_style_review_payload(p) is not true then return false; end if;
   -- SQL btrim and JavaScript trim differ. An ASCII non-whitespace witness
   -- proves runtime nonblankness without guessing about Unicode whitespace.
   if not ((p->>'id')~'[!-~]' and (p->>'name')~'[!-~]') then return false; end if;
   strings:=array['id','name','kind','librarySource','accessTier','registryStatus','contributorName','studioRoutingMode'];
   numbers:=array['studioOrder']; booleans:=array['studioFeatured']; nested:=array['appearance','updates','templateUpdates','targets','studioDestinations'];
 elsif kind in ('template','templatePatch') then
   if kind='template' and not coalesce(jsonb_typeof(p->'id')='string' and (p->>'id')~'[!-~]'
     and jsonb_typeof(p->'name')='string' and (p->>'name')~'[!-~]' and jsonb_typeof(p->'aspectRatio')='string' and jsonb_typeof(p->'freeformCanvas')='object',false) then return false; end if;
   strings:=array['id','name','aspectRatio','formatId','templateSource','templateLibrarySource','templateAccessTier','templateRegistryStatus','templateContributorName','templateLineageId','templateRevisionId','templateParentRevisionId','templateOriginLineageId','templateOriginRevisionId','templateUsage','templateCategory','templateDescription','frameStyle','cardBackgroundImageUrl','cardBackgroundImageFit','cardBorderImageSource','baseBackgroundColor','baseTextColor','defaultElementBorderColor','cardBorderColor','cardBorderWidth','cardBorderStyle','cardBorderRadius'];
   numbers:=array['trimWidthMm','trimHeightMm','templateRevision','templateOrder']; nested:=array['appearance','freeformCanvas','fieldContracts','templatePreviewData'];
 elsif kind in ('element','elementPatch') then
   if kind='element' and not coalesce(jsonb_typeof(p->'id')='string' and jsonb_typeof(p->'name')='string'
      and p->>'type' in ('text','image','icon','shape') and jsonb_typeof(p->'x')='number' and jsonb_typeof(p->'y')='number'
      and jsonb_typeof(p->'width')='number' and jsonb_typeof(p->'height')='number' and jsonb_typeof(p->'zIndex')='number',false) then return false; end if;
   -- Missing text/image content would synthesize a runtime field binding.
   if kind='element' and p->>'type' in ('text','image') and jsonb_typeof(p->'content') is distinct from 'string' then return false; end if;
   strings:=array['id','type','name','parentId','content','imageSource','iconImageSource','iconRenderMode','iconName','shapeKind','shapeRole','textColor','backgroundColor','backgroundImageUrl','fontFamily','fontSize','fontWeight','textAlign','fontStyle','writingMode','letterSpacing','lineHeight','textTransform','textDecoration','generatorFieldKind','padding','borderColor','borderWidth','borderRadius','minHeight','imageObjectFit','imageObjectPositionX','imageObjectPositionY','fillColor','strokeColor'];
   numbers:=array['x','y','width','height','rotation','opacity','zIndex','fontSizePx','textMinFontSizePx','imageScale','imageOffsetX','imageOffsetY','imageRotation','strokeWidth'];
   booleans:=array['flipX','flipY','locked','visible','generatorFieldRequired','textAutoFit']; nested:=array['appearance'];
 elsif kind='appearance' then
   if not public.cardforge_valid_style_review_payload(jsonb_build_object('id','inspection','name','inspection','kind','material','targets',jsonb_build_array('shape'),'appearance',p)) then return false; end if;
   strings:=array['assetSource','assetKind','assetRenderMode','assetTintColor','blendMode','tileMode','dividerAsset','shapeRole'];
   numbers:=array['textureScale','textureOpacity']; nested:=array['material','border','effects','rawCss'];
 elsif kind='material' then
   strings:=array['name','baseColor','textColor','fillColor','strokeColor']; nested:=array['gradient','texture'];
 elsif kind='gradient' then
   strings:=array['type']; numbers:=array['angle']; nested:=array['stops'];
 elsif kind='stop' then
   strings:=array['id','color']; numbers:=array['position','opacity'];
 elsif kind='texture' then
   strings:=array['kind','imageSource','assetSource','assetKind','blendMode','tileMode']; numbers:=array['intensity','scale','textureScale','textureOpacity'];
 elsif kind='border' then
   strings:=array['kind','color','secondaryColor']; numbers:=array['width','radius','innerWidth','outerWidth'];
 elsif kind='effects' then
   strings:='{}'; numbers:=array['shadow','glow','bevel','innerHighlight','overlayOpacity'];
 elsif kind='rawCss' then
   strings:=array['backgroundImage','borderImageSource'];
 elsif kind='canvas' then
   if not coalesce(jsonb_typeof(p->'width')='number' and jsonb_typeof(p->'height')='number'
       and jsonb_typeof(p->'elements')='array',false) then return false; end if;
   strings:='{}'; numbers:=array['width','height','gridSize','hierarchyVersion']; nested:=array['elements'];
 else return false;
 end if;
 for k,v in select * from jsonb_each(p) loop
   if k=any(strings) then
     if jsonb_typeof(v) is distinct from 'string' then return false; end if;
     value:=v#>>'{}';
     if kind='stop' and k='id' and value!~'[!-~]' then return false; end if;
     if k='type' and kind in ('element','elementPatch') and value not in ('text','image','icon','shape') then return false; end if;
     if k='shapeKind' and value not in ('rectangle','ellipse','diamond','hexagon','capsule','banner','notch-panel','bracket-frame','corner-frame','line') then return false; end if;
     if k='iconRenderMode' and value not in ('font','image') then return false; end if;
     if k='imageObjectFit' and value not in ('cover','contain','fill','none','scale-down') then return false; end if;
     if k in ('name','label','description','contributorName','templateContributorName','templateDescription') then continue; end if;
     if kind='stop' and k='color' and not public.cardforge_source_contained_css_image('linear-gradient('||value||', transparent)') then return false; end if;
     if kind='rawCss' and k='backgroundImage' and public.cardforge_source_contained_css_image(value) then continue; end if;
     if k in ('backgroundImageUrl','cardBackgroundImageUrl','cardBorderImageSource')
       and value ~ '^(linear|radial)-gradient\(' and public.cardforge_source_contained_css_image(value) then continue; end if;
     -- Do not infer no dependency from URLs, encoded bytes, CSS indirection,
     -- relative paths or unresolved field bindings. No network reads here.
     if value ~* '(:|/|\\|%[0-9a-f]{2}|url[[:space:]]*\(|var[[:space:]]*\(|<|\{\{)' then
       -- Aspect ratios are typed geometry, not reference strings.
       if k<>'aspectRatio' or value!~'^[0-9]+:[0-9]+$' then return false; end if;
     end if;
     -- Typed sources are URLs, not CSS values: truthy 'none' can render as
     -- url(none). Only raw CSS properties interpret CSS none as no image.
     if k in ('assetSource','dividerAsset','imageSource','iconImageSource','backgroundImageUrl','cardBackgroundImageUrl','cardBorderImageSource')
       and value<>'' then return false; end if;
     if kind='rawCss' and k in ('backgroundImage','borderImageSource')
       and value<>'' and not (k='backgroundImage' and value='none') then return false; end if;
     if k='content' and (kind='elementPatch' or p->>'type'='image') and value<>'' then return false; end if;
   elsif k=any(numbers) then
     if jsonb_typeof(v) is distinct from 'number' then return false; end if;
     if abs((v#>>'{}')::numeric)>1.7976931348623157e308 then return false; end if;
     if k in ('width','height') and ((kind='border' and (v#>>'{}')::numeric<0)
       or (kind<>'border' and (v#>>'{}')::numeric<=0)) then return false; end if;
   elsif k=any(booleans) then
     if jsonb_typeof(v) is distinct from 'boolean' then return false; end if;
   elsif k=any(nested) then
     if k in ('targets','studioDestinations') then
       if jsonb_typeof(v) is distinct from 'array' then return false; end if;
       if exists(select 1 from jsonb_array_elements(v) e where jsonb_typeof(e) is distinct from 'string') then return false; end if;
     elsif k='fieldContracts' then
       if v is distinct from '[]'::jsonb then return false; end if;
     elsif k='templatePreviewData' then
       if v is distinct from '{}'::jsonb then return false; end if;
     elsif k in ('elements','stops') then
       if jsonb_typeof(v) is distinct from 'array' then return false; end if;
       for child in select * from jsonb_array_elements(v) loop
         if not public.cardforge_catalog_consumer_inspectable(child,case when k='elements' then 'element' else 'stop' end,depth+1) then return false; end if;
       end loop;
     else
       child_kind:=case k when 'updates' then 'elementPatch' when 'templateUpdates' then 'templatePatch' when 'freeformCanvas' then 'canvas' else k end;
       if not public.cardforge_catalog_consumer_inspectable(v,child_kind,depth+1) then return false; end if;
     end if;
   else return false;
   end if;
 end loop;
 return true;
end $$;


create or replace function public.cardforge_catalog_trash_entry_reasons(p_lineage_id uuid)
returns text[] language plpgsql security invoker set search_path='' as $$
declare l public.cardforge_pipeline_asset_lineages%rowtype; r public.cardforge_asset_registry%rowtype;
  reasons text[] := '{}'; consumer record; payload jsonb; key text;
  ids text[]; sources text[]; opaque boolean:=false; referenced boolean:=false;
begin
  select * into l from public.cardforge_pipeline_asset_lineages where id=p_lineage_id;
  select * into r from public.cardforge_asset_registry where asset_id=l.registry_asset_id;
  if l.catalog_destructive_uncertainty is not null then reasons:=array_append(reasons,l.catalog_destructive_uncertainty); end if;
  if l.purge_state is not null or l.catalog_claim_token is not null or l.catalog_claimed_at is not null
    or exists(select 1 from public.cardforge_contributor_asset_submissions s where s.lineage_id=l.id
      and (s.purge_state is not null or s.purge_claim_token is not null or s.purge_claimed_at is not null or s.owner_purge_requested_at is not null))
    then reasons:=array_append(reasons,'destructive_attempt_requires_reconciliation'); end if;
  if r.asset_id is null or r.contributor_submission_id is null then
    reasons:=array_append(reasons,'catalog_registry_identity_unavailable');
  end if;
  if exists(select 1 from public.cardforge_contributor_asset_submissions newer
    join public.cardforge_contributor_asset_submissions published_base on published_base.id=r.contributor_submission_id
    where newer.lineage_id=l.id and newer.revision_number>published_base.revision_number) then
    reasons:=array_append(reasons,'newer_revision_requires_review');
  end if;
  if exists(select 1 from public.cardforge_contributor_asset_submissions source where source.lineage_id=l.id
    and (source.source_storage_bucket is not null or source.source_storage_path is not null)
    and not coalesce((source.source_storage_bucket='cardforge-contributor-assets'
      and source.source_storage_path=l.upload_source_path and l.upload_state='owned'
      and l.upload_operation_token is not null and l.upload_request is not null
      and exists(select 1 from public.cardforge_contributor_asset_submissions receipt
        where receipt.id=l.upload_submission_id and receipt.lineage_id=l.id
          and receipt.source_upload_token=l.upload_operation_token
          and receipt.source_storage_bucket=source.source_storage_bucket
          and receipt.source_storage_path=source.source_storage_path)),false)) then
    reasons:=array_append(reasons,'upload_cleanup_commitment_unverified');
  end if;
  -- Templates, fonts and presets also supply the runtime bootstrap. Do not
  -- hide them before installed-resolution compatibility has been established.
  if r.asset_type is null or r.asset_type not in ('image','texture','divider','icon') then
    reasons:=array_append(reasons,'installed_runtime_resolution_unverified');
  end if;
  ids:=array_remove(array[r.asset_id,l.id::text],null)||array(select id::text from public.cardforge_contributor_asset_submissions where lineage_id=l.id);
  select coalesce(array_agg(distinct u) filter(where nullif(u,'') is not null),'{}') into sources
    from (select r.url u union all select r.preview_url
      union all select s.source_url from public.cardforge_contributor_asset_submissions s where s.lineage_id=l.id
      union all select s.preview_url from public.cardforge_contributor_asset_submissions s where s.lineage_id=l.id) x;
  -- Exact stored source/preview aliases only: never derive equivalence from a
  -- display name, filename, URL rewrite, failed fetch or caller-provided scan.

  -- Respect readRegistryContentAsset precedence, but do not skip an invalid
  -- non-NULL candidate: native and JS validation may differ at their edges.
  -- Such a candidate stays opaque rather than clearing a later fallback.
  -- Only Styles have metadata fallback. NULL source is never backfilled.
  -- Sets have no persisted decoded package in the native authority: their URL
  -- and summary metadata cannot establish complete dependency inventory.
  for consumer in select a.*,s.source_payload from public.cardforge_asset_registry a
    left join public.cardforge_contributor_asset_submissions s on s.id=a.contributor_submission_id
    where a.asset_type in ('elementPreset','template','set') loop
    payload:=consumer.source_payload;
    if consumer.asset_type='elementPreset' then
      if payload is null or payload='null'::jsonb then
        payload:=null;
        foreach key in array array['style','elementPreset','payload'] loop
          if consumer.metadata->key is not null and consumer.metadata->key<>'null'::jsonb then
            payload:=consumer.metadata->key; exit;
          end if;
        end loop;
      end if;
    end if;
    if public.cardforge_catalog_consumer_mentions(payload,ids,sources) then referenced:=true; end if;
    if consumer.asset_type='set' or not public.cardforge_catalog_consumer_inspectable(payload,
      case when consumer.asset_type='elementPreset' then 'style' else 'template' end) then opaque:=true; end if;
  end loop;

  -- Unpublished and historical native payloads remain consumers. A linked
  -- legacy NULL Style was inspected through its authoritative registry above;
  -- never substitute that current metadata for an unlinked historical revision.
  for consumer in select s.* from public.cardforge_contributor_asset_submissions s
    where s.lineage_id is distinct from l.id
      and not exists(select 1 from public.cardforge_asset_registry a where a.contributor_submission_id=s.id
        and a.asset_type in ('elementPreset','template','set')) loop
    if public.cardforge_catalog_consumer_mentions(consumer.source_payload,ids,sources) then referenced:=true; end if;
    if consumer.asset_type in ('elementPresets','templates','sets') then
      if consumer.asset_type='sets' or not public.cardforge_catalog_consumer_inspectable(consumer.source_payload,
        case when consumer.asset_type='elementPresets' then 'style' else 'template' end) then opaque:=true; end if;
    elsif consumer.source_payload is not null then
      -- No negative proof for an unsupported payload kind.
      opaque:=true;
    end if;
  end loop;
  if referenced then reasons:=array_append(reasons,'pipeline_identity_consumer_requires_resolution'); end if;

  -- Inspect the proven source-contained Studio subset in the existing SHARE-
  -- locked mutation transaction; never consume an earlier service-side scan.
  for consumer in select document_payload,revision,catalog_dependencies from public.cardforge_studio_documents loop
    if public.cardforge_catalog_consumer_mentions(consumer.document_payload,ids,sources)
      or (public.cardforge_studio_dependency_binding_valid(consumer.document_payload,consumer.revision,consumer.catalog_dependencies)
        and public.cardforge_studio_dependencies_mention(consumer.catalog_dependencies->'references',ids,sources)) then
      if not ('studio_identity_consumer_requires_resolution'=any(reasons)) then
        reasons:=array_append(reasons,'studio_identity_consumer_requires_resolution');
      end if;
    elsif not public.cardforge_studio_dependency_binding_valid(consumer.document_payload,consumer.revision,consumer.catalog_dependencies)
      or consumer.catalog_dependencies->'complete' is distinct from 'true'::jsonb then opaque:=true;
    end if;
  end loop;
  if opaque then reasons:=array_append(reasons,'json_consumer_inventory_unverified'); end if;
  return reasons;
end $$;

create or replace function public.cardforge_catalog_trash_inventory_details(p_lineage_id uuid)
returns jsonb language sql stable security invoker set search_path='' as $$
with target as (
 select l.id,r.asset_id,r.url,r.preview_url from public.cardforge_pipeline_asset_lineages l
 left join public.cardforge_asset_registry r on r.asset_id=l.registry_asset_id where l.id=p_lineage_id
), aliases as (
 select array_remove(array[t.asset_id,t.id::text],null)||array(select id::text from public.cardforge_contributor_asset_submissions where lineage_id=t.id) ids,
 array(select distinct u from (
 select t.url u union all select t.preview_url union all
 select s.source_url from public.cardforge_contributor_asset_submissions s where s.lineage_id=t.id union all
 select s.preview_url from public.cardforge_contributor_asset_submissions s where s.lineage_id=t.id
 ) urls where nullif(u,'') is not null) sources from target t
), consumers as (
 select 'registry' origin,a.asset_id record_id,a.asset_type kind,
 case when a.asset_type='elementPreset' then coalesce(nullif(s.source_payload,'null'::jsonb),nullif(a.metadata->'style','null'::jsonb),nullif(a.metadata->'elementPreset','null'::jsonb),nullif(a.metadata->'payload','null'::jsonb)) else s.source_payload end payload, null::integer revision, null::jsonb interpretation
 from public.cardforge_asset_registry a left join public.cardforge_contributor_asset_submissions s on s.id=a.contributor_submission_id
 where a.asset_type in ('elementPreset','template','set')
 union all
 select 'submission',s.id::text,s.asset_type,s.source_payload,null::integer,null::jsonb from public.cardforge_contributor_asset_submissions s
 where s.lineage_id is distinct from p_lineage_id and not exists(
 select 1 from public.cardforge_asset_registry a where a.contributor_submission_id=s.id and a.asset_type in ('elementPreset','template','set'))
 union all select 'studio',id::text,'studio',document_payload,revision,catalog_dependencies from public.cardforge_studio_documents
), evaluated as (
 select c.*,(public.cardforge_catalog_consumer_mentions(payload,a.ids,a.sources)
   or (kind='studio' and public.cardforge_studio_dependency_binding_valid(payload,revision,interpretation)
     and public.cardforge_studio_dependencies_mention(interpretation->'references',a.ids,a.sources))) referenced,
 case when kind in ('set','sets') then 'set_package_not_natively_decoded'
 when kind='studio' and not public.cardforge_studio_dependency_binding_valid(payload,revision,interpretation) then 'studio_interpretation_missing_or_stale'
 when kind='studio' and interpretation->'complete' is distinct from 'true'::jsonb then 'outside_supported_native_payload_subset'
 when kind in ('elementPreset','elementPresets','template','templates') then
 case when payload is null or payload='null'::jsonb then 'missing_native_payload_external_fallback_possible'
 when jsonb_typeof(payload)<>'object' then 'non_object_payload'
 when kind in ('elementPreset','elementPresets') and public.cardforge_valid_style_review_payload(payload) is not true then 'invalid_native_style_payload'
 when not public.cardforge_catalog_consumer_inspectable(payload,case when kind in ('elementPreset','elementPresets') then 'style' else 'template' end) then 'outside_supported_native_payload_subset' end
 when kind<>'studio' and payload is not null then 'unsupported_payload_kind' end condition
 from consumers c cross join aliases a
)
select coalesce(jsonb_agg(jsonb_build_object('origin',origin,'recordId',record_id,'payloadKind',kind,
 'conditions',to_jsonb(array_remove(array[
 case when referenced then 'target_identity_or_source_reference' end,
 -- Match the existing Studio gate: a reference is blocking in its own right.
 case when origin='studio' and referenced then null else condition end],null)))
 order by origin,record_id),'[]'::jsonb)
from evaluated where referenced or condition is not null;
$$;


